// Normalize popular-post links generated by hexo-related-popular-posts on Windows.
hexo.extend.helper.register('popular_posts_fixed', function(options, post) {
  var original = hexo.extend.helper.get('popular_posts');
  if (!original) return '';

  var html = original.call(this, options, post);
  return html.replace(/href="\\([^\"]*)"/g, function(match, path) {
    return 'href="/' + path.replace(/\\/g, '/') + '"';
  });
});
